// Rule 843: code is printed only after a successful payment.
// The amount is the final total of the receipt after other discounts.
if (check.state != 2) return false

def total = check.orderClient.sum_order ?: 0
def loyaltyCode = check.orderClient.interimData['uployalCode']?.toString()?.trim()

// The customer must be a Uployal loyalty-program participant.
return total >= 500 && loyaltyCode
